contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address observer, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(observer == address(this));

        uint beforeObserver = c.getBalance(observer); if (__ESBMC_reverted()) return;

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint afterObserver = c.getBalance(observer); if (__ESBMC_reverted()) return;

        assert(afterObserver >= beforeObserver);
    }

    receive() external payable {}
}

