// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(address observer, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        observer = address(this);
        uint256 beforeObserver;
        try c.getBalance(observer) returns (uint256 __r) { beforeObserver = __r; } catch { return; }
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 afterObserver;
        try c.getBalance(observer) returns (uint256 __r) { afterObserver = __r; } catch { return; }
        assertTrue(afterObserver >= beforeObserver);
    }

    function testFuzz_run(address observer, uint256 amount) public {
        _run(observer, amount);
    }

    receive() external payable {}
}
